//! KbWrite — a local-first, Obsidian-style knowledge base written in native Rust.
mod ai;
mod app;
mod blocks;
mod editor;
mod graph;
mod settings;
mod vault;

use eframe::egui;

/// Window icon (embedded raw RGBA, generated by scripts/make_icon.py).
fn app_icon() -> egui::IconData {
    const W: u32 = 256;
    const H: u32 = 256;
    egui::IconData {
        width: W,
        height: H,
        rgba: include_bytes!("../assets/icon_256.rgba").to_vec(),
    }
}

fn main() -> eframe::Result<()> {
    let options = eframe::NativeOptions {
        viewport: egui::ViewportBuilder::default()
            .with_inner_size([1240.0, 820.0])
            .with_min_inner_size([720.0, 480.0])
            .with_title("KbWrite")
            .with_icon(app_icon()),
        ..Default::default()
    };

    eframe::run_native(
        "KbWrite",
        options,
        Box::new(|cc| {
            // Fonts: Phosphor icons + platform default UI/code fonts.
            cc.egui_ctx.set_fonts(app::font_definitions());
            Ok(app::KbWriteApp::new(cc) as Box<dyn eframe::App>)
        }),
    )
}
